<style>
.schedule-timeline,.schedule-dialog,.schedule-day-card,.schedule-advisory-card{--schedule-bg:#f5f9f5;--schedule-surface:#fff;--schedule-text:#153c2e;--schedule-muted:#5d7368;--schedule-line:#c7d9cd;color:var(--schedule-text)}
.schedule-day-card{margin:20px;padding:24px;background:var(--schedule-bg);border:1px solid var(--schedule-line);border-radius:18px}.schedule-day-head{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:22px}.schedule-day-head h3{margin:0!important;color:var(--schedule-text)!important;font-size:19px!important}.schedule-day-head p{margin:5px 0 0!important;color:var(--schedule-muted)!important;font-size:13px!important}
.schedule-slot{display:grid;grid-template-columns:125px minmax(0,1fr);gap:20px;padding-bottom:22px}.schedule-slot-time{display:flex;flex-direction:column;gap:8px;padding-top:14px;color:var(--schedule-text)}.schedule-slot-time strong{font-size:14px}.schedule-slot-events{position:relative;padding-left:23px;border-left:2px solid var(--schedule-line);display:grid;gap:10px}.schedule-slot-events:before{content:'';position:absolute;left:-6px;top:19px;width:10px;height:10px;border-radius:50%;background:#315c43;box-shadow:0 0 0 4px var(--schedule-bg)}
.schedule-event{padding:16px 18px;background:var(--schedule-surface);border:1px solid var(--schedule-line);border-radius:12px}.schedule-event.is-selected{border-color:#315c43;box-shadow:0 0 0 2px #315c4330;background:#e5f0e8}.schedule-event-top{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:9px}.schedule-event-label{font-size:12px;font-weight:700}.schedule-event-status{font-size:11px;color:var(--schedule-muted)}.schedule-event-case{display:flex;align-items:center;gap:8px;font-weight:700;font-size:14px;color:var(--schedule-text)!important;text-decoration:none}.schedule-event-case span{font-weight:500}.schedule-event-case i{margin-left:auto}.schedule-event p{font-size:12px!important;margin:8px 0 0!important;color:var(--schedule-muted)!important}.schedule-same-time{font-size:11px;background:#fff1cf;color:#805b16;border:1px solid #ecd69b;border-radius:7px;padding:5px 7px;align-self:flex-start}
.schedule-open,.schedule-done{min-height:44px;padding:10px 16px;border:1px solid var(--schedule-line);border-radius:10px;background:#31583d;color:#fff!important;font-size:13px;font-weight:700;cursor:pointer}.schedule-open:hover,.schedule-done:hover{background:#24452f}.schedule-open:focus-visible,.schedule-close:focus-visible,.schedule-done:focus-visible,.schedule-event-case:focus-visible{outline:3px solid #c18b30;outline-offset:3px}
.schedule-advisory-card{margin:16px 0;padding:20px;border:1px solid #e1cf98;border-radius:16px;background:var(--schedule-bg)}.schedule-advisory-card h3{color:var(--schedule-text)!important;font-size:18px!important;margin:0 0 5px!important}.schedule-advisory-card>p{color:var(--schedule-muted)!important;font-size:13px!important;margin:0 0 16px!important}.schedule-advisory-row{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:12px 0;border-top:1px solid var(--schedule-line)}.schedule-advisory-row strong{font-size:14px}.schedule-advisory-row small{display:block;color:var(--schedule-muted);margin-top:4px}
.schedule-dialog{width:min(740px,calc(100vw - 32px));max-height:calc(100dvh - 48px);padding:0;border:1px solid var(--schedule-line);border-radius:20px;background:var(--schedule-bg);box-shadow:0 24px 80px #09251940}.schedule-dialog::backdrop{background:rgba(12,34,25,.58)}.schedule-dialog-head{display:flex;justify-content:space-between;gap:16px;padding:24px;border-bottom:1px solid var(--schedule-line)}.schedule-dialog-head h2{color:var(--schedule-text)!important;font-size:22px!important;margin:7px 0!important}.schedule-dialog-head p,.schedule-dialog-head small{color:var(--schedule-muted)!important;margin:0!important;font-size:13px!important}.schedule-close{width:44px;height:44px;flex-shrink:0;border:1px solid var(--schedule-line);border-radius:10px;color:var(--schedule-text);background:var(--schedule-surface);cursor:pointer}.schedule-dialog-body{padding:24px}.schedule-advisory-note{display:flex;gap:10px;background:#fff6df;border:1px solid #ebd7a2;color:#805b16!important;padding:13px 15px;border-radius:10px;font-size:13px!important;margin:0 0 24px!important}.schedule-dialog footer{padding:16px 24px;display:flex;justify-content:flex-end;border-top:1px solid var(--schedule-line)}.schedule-modal-open{overflow:hidden}
html[data-theme="dark"] .schedule-timeline,html[data-theme="dark"] .schedule-dialog,html[data-theme="dark"] .schedule-day-card,html[data-theme="dark"] .schedule-advisory-card{--schedule-bg:#132b20;--schedule-surface:#193528;--schedule-text:#edf6ef;--schedule-muted:#b1c8b9;--schedule-line:#365844}html[data-theme="dark"] .schedule-event.is-selected{background:#244b35;border-color:#7faa8b}html[data-theme="dark"] .schedule-advisory-note,html[data-theme="dark"] .schedule-same-time{background:#3c321c;color:#f2d594!important;border-color:#70603b}
@media(max-width:600px){.schedule-day-card{margin:12px;padding:16px}.schedule-slot{grid-template-columns:1fr;gap:10px}.schedule-slot-time{padding:0;flex-direction:row;align-items:center;flex-wrap:wrap}.schedule-event-top{align-items:flex-start}.schedule-event-case{flex-wrap:wrap}.schedule-dialog-head,.schedule-dialog-body{padding:18px}.schedule-dialog-head h2{font-size:19px!important}.schedule-day-head,.schedule-advisory-row{align-items:flex-start;flex-direction:column}.schedule-advisory-row .schedule-open{width:100%}}
html[data-theme] body.panel-shell-body :is(.schedule-dialog,.schedule-day-card) .schedule-event-case,
html[data-theme] body.panel-shell-body :is(.schedule-dialog,.schedule-day-card) .schedule-event-case :is(span,i){color:var(--schedule-text)!important}
.schedule-wake-progress{width:100%;height:8px;accent-color:#315c43;border:0;border-radius:6px;overflow:hidden}.schedule-wake-progress::-webkit-progress-bar{background:#d6e3da;border-radius:6px}.schedule-wake-progress::-webkit-progress-value{background:#315c43;border-radius:6px}
html[data-theme='dark'] body.panel-shell-body .rp-header-filters{background:#132b20!important;border-color:#365844!important}
html[data-theme='dark'] body.panel-shell-body .rp-header-filters :is(.form-select,.form-input){background:#193528!important;color:#edf6ef!important;border-color:#365844!important;color-scheme:dark}
html[data-theme='dark'] body.panel-shell-body .rp-header-filters :is(label,.rp-filter-chevron){color:#b1c8b9!important}
html[data-theme='dark'] body.panel-shell-body .rp-header-filters{background:#132b20!important;border-color:#365844!important}
html[data-theme='dark'] body.panel-shell-body .rp-header-filters :is(.form-select,.form-input){background:#193528!important;color:#edf6ef!important;border-color:#365844!important;color-scheme:dark}
html[data-theme='dark'] body.panel-shell-body .rp-header-filters :is(label,.rp-filter-chevron){color:#b1c8b9!important}
.schedule-dialog :is(.calendar-control,.schedule-close),.schedule-open,.schedule-done,.schedule-event-case{transition:background-color .15s ease,border-color .15s ease;color:inherit;cursor:pointer}
.schedule-open:hover,.schedule-done:hover{background:var(--ops-primary-hover,#1c4232);border-color:var(--ops-primary-hover,#1c4232)}
.schedule-dialog .schedule-close:hover,.schedule-event-case:hover{background:var(--records-hover,#c5d3bc);border-color:var(--ops-border-strong,#91a38b)}
@media(prefers-reduced-motion:reduce){.schedule-dialog :is(.calendar-control,.schedule-close),.schedule-open,.schedule-done,.schedule-event-case{transition:none}}
.ref-schedule-coordination{display:inline-flex;align-items:center;gap:6px;margin-top:8px;padding:4px 8px;border-radius:6px;background:#f5ecd5;color:#6b4d08!important;font-size:12px;line-height:1.5}
html[data-theme=dark] .ref-schedule-coordination{background:#3c321c;color:#f0d892!important}
html[data-theme] body.panel-shell-body.staff-ui .staff-dashboard-v2 .ref-activity-row>div>span:not(.ref-field-label):not(.ref-meta):not(.ref-code):not(.ref-package):not(.status-pill){color:var(--staff-ink)!important}
.dashboard-activity-pagination{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;padding:12px 20px;border-top:1px solid var(--staff-border);font-size:12px;color:var(--staff-muted);background:var(--staff-card)}
.dashboard-activity-pagination>div{display:flex;align-items:center;gap:12px}
.dashboard-activity-pagination :is(a,button){display:inline-flex;align-items:center;justify-content:center;width:36px;height:36px;border:1px solid var(--staff-border);border-radius:8px;background:var(--staff-card);color:var(--staff-ink)!important;text-decoration:none;cursor:pointer}
.dashboard-activity-pagination a:hover{background:var(--staff-hover)}
.dashboard-activity-pagination button:disabled{opacity:.4;cursor:default}
.dashboard-activity-pagination a:focus-visible{outline:2px solid var(--staff-action);outline-offset:2px}
html[data-theme] body.panel-shell-body.staff-ui .staff-dashboard-v2 .dashboard-schedule-count{margin:0!important;padding:12px 20px 0;font-size:12px!important;color:var(--staff-muted)!important;line-height:1.5}
</style>
